import type {
  OAuthHelpers,
  OAuthProviderOptions,
} from "@cloudflare/workers-oauth-provider";
import type { NativePublicFetchOptions } from "./native-public-fetch.ts";

/** The reviewed upstream module, generated by build-native-oauth.ts. Importing
 * its types never brings the Worker runtime into a native process. */
export interface NativeOAuthModule {
  readonly publicFetchProtection?: true;
  OAuthProvider: new <Environment>(
    options: OAuthProviderOptions<Environment>,
  ) => {
    fetch(
      request: Request,
      env: Environment,
      ctx: NativeOAuthContext,
    ): Promise<Response>;
  };
  getOAuthApi<Environment>(
    options: OAuthProviderOptions<Environment>,
    env: Environment,
  ): OAuthHelpers;
}

export interface NativeOAuthBundle extends NativeOAuthModule {
  publicFetchProtection: true;
  createNativeOAuthModule(
    options?: NativePublicFetchOptions,
  ): NativeOAuthModule;
}

/** Object handlers receive the native process context, extended by upstream
 * with the decrypted token props. Worker-only context methods are not emulated. */
export interface NativeOAuthContext {
  waitUntil(promise: Promise<unknown>): void;
  props?: unknown;
}

export async function loadNativeOAuthProvider(
  url: URL,
): Promise<NativeOAuthBundle> {
  const provider: NativeOAuthBundle = await import(url.href);
  if (
    typeof provider.OAuthProvider !== "function" ||
    typeof provider.getOAuthApi !== "function" ||
    typeof provider.createNativeOAuthModule !== "function" ||
    provider.publicFetchProtection !== true
  ) {
    throw new TypeError("Invalid generated native OAuth provider");
  }
  return provider;
}
